makeBtn(ContentPages["Config"],"SAVE AS NAMED",curY,function()
    local name=ConfigNameBox.Text if name=="" then Notify("Enter name first!") return end
    local cfg=GetCurrentConfigTable() cfg.name=name cfg.savedAt=os.date("%Y-%m-%d %H:%M")
    SavedConfigs[name]=cfg _G.MNK_Configs=SavedConfigs
    local code=EncodeConfigToCode(cfg) CodeBox.Text=code Notify("Saved: "..name)
    pcall(function() if writefile then writefile("mnk_d3vxz_configs.json", HttpService:JSONEncode(SavedConfigs)) end end)
end,Color3.fromRGB(0,180,80),7) curY=curY+22

makeBtn(ContentPages["Config"],"LOAD NAMED",curY,function()
    local name=ConfigNameBox.Text if name=="" then Notify("Enter name") return end
    local cfg=SavedConfigs[name]
    pcall(function() if not cfg and readfile and isfile and isfile("mnk_d3vxz_configs.json") then local data=readfile("mnk_d3vxz_configs.json") local decoded=HttpService:JSONDecode(data) SavedConfigs=decoded _G.MNK_Configs=decoded cfg=decoded[name] end end)
    if cfg then ApplyConfigTable(cfg) Notify("Loaded: "..name) else Notify("Not found: "..name) end
end,Color3.fromRGB(138,43,226),7) curY=curY+22

makeBtn(ContentPages["Config"],"EXPORT CODE (COPY)",curY,function()
    local cfg=GetCurrentConfigTable() local code=EncodeConfigToCode(cfg) CodeBox.Text=code
    pcall(function() if setclipboard then setclipboard(code) Notify("Copied!") else Notify("Code in box - copy manually") end end)
end,Color3.fromRGB(60,60,180),7) curY=curY+22

makeBtn(ContentPages["Config"],"IMPORT CODE FROM BOX",curY,function()
    local code=CodeBox.Text if code=="" or code:find("will appear") then Notify("Paste code first") return end
    local tbl=DecodeCodeToConfig(code)
    if tbl then ApplyConfigTable(tbl) Notify("Imported: "..(tbl.name or "shared")) if tbl.name then SavedConfigs[tbl.name]=tbl _G.MNK_Configs=SavedConfigs end else Notify("Invalid code!") end
end,Color3.fromRGB(200,100,20),7) curY=curY+22

do local box=makeBox(ContentPages["Config"],curY,70) curY=curY+74 local listLbl=Instance.new("TextLabel",box) listLbl.Size=UDim2.new(0.96,0,0,66) listLbl.Position=UDim2.new(0.02,0,0,2) listLbl.BackgroundTransparency=1 listLbl.Text="How sharing works:\n1. SAVE with name -> code appears in green box\n2. Copy code (auto copy if setclipboard)\n3. Send to friend\n4. Friend pastes in green box -> IMPORT" listLbl.TextColor3=Color3.fromRGB(180,160,200) listLbl.TextSize=6 listLbl.Font=Enum.Font.GothamMedium listLbl.TextXAlignment=Enum.TextXAlignment.Left task.spawn(function() while true do task.wait(2) if not listLbl.Parent then break end local names={} for k,_ in pairs(SavedConfigs) do table.insert(names,k) end if #names>0 then listLbl.Text="Saved: "..table.concat(names, ", ").."\n\nShare: SAVE -> copy code -> send -> friend IMPORT" end end end) end

